args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-29-omics-library-next/cellchat');S<-file.path(P,'biofigure');source(file.path(S,'scripts/figure_style.R'));library(ggplot2);library(patchwork);library(ggrepel);font<-bf_font('Arial');q<-jsonlite::fromJSON(file.path(W,'metadata.json'));stem<-q$stem;PD<-file.path(P,'results/plot_data');rd<-function(n)read.csv(file.path(PD,paste0(stem,'_',n,'.csv')),check.names=FALSE);nodes<-rd('nodes');r<-rd('ring_nodes');e<-rd('ring_edges');cols<-setNames(nodes$color,nodes$cell_type)
curve<-do.call(rbind,lapply(seq_len(nrow(e)),function(i){t<-seq(0,1,length.out=60);a<-e[i,];data.frame(edge=i,x=(1-t)^2*a$source_x+t^2*a$target_x,y=(1-t)^2*a$source_y+t^2*a$target_y,weight=a$weight,color=a$color)}))
